#!/usr/bin/env bash
# The previous fix added a log file, but it came back completely EMPTY (0
# bytes) on the real Windows install - which is itself a real, diagnostic
# clue, not a dead end. Two defensive fixes, both verified for real before
# shipping:
#
# 1. logging.basicConfig() is a silent no-op if anything already attached a
#    handler to the root logger before our setup_logging() runs - it just
#    does nothing, with no error. Reproduced this exact scenario (poison
#    the root logger first, then call the old setup_logging()) and got an
#    EMPTY file, byte-for-byte matching what you saw. Fixed with
#    force=True, confirmed that resolves it.
# 2. ensure_registered() only ever caught ApiError - any other exception
#    (a network/SSL/certificate error, most likely candidate for a fresh
#    bundled Python runtime on a real machine) would crash the background
#    thread completely uncaught, invisible for a headless service. Now
#    caught broadly and logged with a full traceback. Verified for real:
#    simulated an SSLError during registration and confirmed the full
#    traceback now lands in agent.log instead of vanishing.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz"
base64 -d > app/static/installers/opslab-agent.tar.gz << 'B64_EOF_MARKER'

B64_EOF_MARKER

echo "==> Verifying the tarball contains both fixes"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
mkdir -p /tmp/verify_fix_$$
tar -xzf app/static/installers/opslab-agent.tar.gz -C /tmp/verify_fix_$$
OK=1
if ! grep -q "force=True" /tmp/verify_fix_$$/agent/main.py; then
    echo "    MISSING: force=True fix"
    OK=0
fi
if ! grep -q "Registration failed with an unexpected error" /tmp/verify_fix_$$/agent/main.py; then
    echo "    MISSING: broad exception handler"
    OK=0
fi
rm -rf /tmp/verify_fix_$$
if [[ $OK -eq 1 ]]; then
    echo "    Confirmed: both fixes present."
else
    echo "    ERROR: one or more fixes missing from the tarball!"
    exit 1
fi

echo ""
echo "Done. Restart the app:"
echo "    pkill -f 'admin_panel/run.py'"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > /root/admin_panel/app.log 2>&1 &"
echo ""
echo "Then on Windows, one command at a time:"
echo "    sc.exe stop OpsLabAgent"
echo "    sc.exe delete OpsLabAgent"
echo '    Remove-Item "C:\Program Files\OpsLabAgent" -Recurse -Force'
echo "(re-run the install command from the instances page)"
echo '    Get-Content "C:\ProgramData\OpsLabAgent\agent.log" -Tail 30'
echo ""
echo "This time agent.log should have real content - either a successful"
echo "registration, or (just as useful) the actual error stopping it."
